/* [MODULE MỚI] Helper dùng cho các chuỗi ĐỘNG (có ghép biến số/thời gian...),
   vì cơ chế i18nWalk() chỉ khớp được các text node TĨNH trùng khớp 100% với
   I18N_DICT. Gọi i18nT('...') ngay tại nơi build chuỗi để lấy bản dịch theo
   currentAppLang, phần biến số vẫn giữ nguyên (không dịch). */
function i18nT(str){
  if(currentAppLang === 'vi') return str;
  const entry = I18N_DICT[str];
  return (entry && entry[currentAppLang]) || str;
}
function i18nTranslateNode(node, lang){
  let original = node.__viOriginal;
  if(original === undefined){
    const raw = node.nodeValue;
    const trimmed = raw.trim();
    if(trimmed && Object.prototype.hasOwnProperty.call(I18N_DICT, trimmed)){
      const idx = raw.indexOf(trimmed);
      node.__viOriginal = trimmed;
      node.__viLead = raw.slice(0, idx);
      node.__viTrail = raw.slice(idx + trimmed.length);
      original = trimmed;
    } else {
      node.__viOriginal = null;
      return;
    }
  }
  if(!original) return;
  const entry = I18N_DICT[original];
  if(!entry) return;
  const text = (lang === 'vi') ? original : (entry[lang] || original);
  node.nodeValue = (node.__viLead || '') + text + (node.__viTrail || '');
}
function i18nWalk(root, lang){
  if(root.nodeType === 3){ i18nTranslateNode(root, lang); return; }
  if(root.nodeType !== 1) return;
  const tag = root.tagName;
  if(tag === 'SCRIPT' || tag === 'STYLE' || tag === 'NOSCRIPT') return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(n){
      const p = n.parentElement;
      if(!p) return NodeFilter.FILTER_REJECT;
      const pt = p.tagName;
      if(pt === 'SCRIPT' || pt === 'STYLE' || pt === 'NOSCRIPT') return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });
  let n;
  while((n = walker.nextNode())) i18nTranslateNode(n, lang);
}
function updateLangUI(lang){
  const sel = document.getElementById('langSelect');
  if(sel) sel.value = lang;
}
function setAppLanguage(lang){
  currentAppLang = lang;
  try{ localStorage.setItem(LANG_LS_KEY, lang); }catch(e){}
  updateLangUI(lang);
  i18nWalk(document.body, lang);
  showToast(lang === 'vi' ? '✅ Đã chuyển sang Tiếng Việt' : '✅ Language updated');
}
(function initLang(){
  let saved = null;
  try{ saved = localStorage.getItem(LANG_LS_KEY); }catch(e){}
  currentAppLang = saved || 'vi';
  updateLangUI(currentAppLang);
  if(currentAppLang !== 'vi') i18nWalk(document.body, currentAppLang);
  const langObserver = new MutationObserver(function(mutations){
    if(currentAppLang === 'vi') return;
    mutations.forEach(function(m){
      m.addedNodes.forEach(function(n){ i18nWalk(n, currentAppLang); });
    });
  });
  langObserver.observe(document.body, {childList:true, subtree:true});
})();
